"use client";

import dynamic from "next/dynamic";
import { PresentationControls, useGLTF, useTexture } from "@react-three/drei";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { Suspense, useEffect, useLayoutEffect, useMemo, useRef, type ReactNode } from "react";
import * as THREE from "three";
import { COPY } from "@/config/copy";
import { BODY_MATERIAL_NAME } from "@/config/vehicles";

// Keep the supplied image in this page so no additional asset file is needed.
const WINDOW_IMAGE = "data:image/png;base64,";
const MODEL_URL = "/models/camry.glb?v=2";

function Car() {
  const viewport = useThree((state) => state.size);
  const gltf = useGLTF(MODEL_URL);
  const { scene, bounds } = useMemo(() => {
    const cloned = gltf.scene.clone(true);
    cloned.traverse((object) => {
      const mesh = object as THREE.Mesh;
      if (!mesh.isMesh || !mesh.material) return;
      mesh.material = Array.isArray(mesh.material)
        ? mesh.material.map((material) => material.clone())
        : mesh.material.clone();
    });
    cloned.scale.setScalar(1);
    cloned.position.set(0, 0, 0);
    cloned.rotation.set(0, Math.PI * 0.42, 0);
    // Measure the actual vertices before attaching to the rotating parent.
    // This keeps the pivot independent of the current drag angle.
    const bounds = new THREE.Box3().setFromObject(cloned, true);
    return { scene: cloned, bounds };
  }, [gltf.scene]);

  useLayoutEffect(() => {
    scene.traverse((object) => {
      const mesh = object as THREE.Mesh;
      if (!mesh.isMesh || !mesh.material) return;
      const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const material of materials) {
        const surface = material as THREE.MeshPhysicalMaterial;
        const glass = /glass|window/i.test(material.name);
        const glow = /glow/i.test(material.name);
        if ("emissive" in surface) {
          surface.emissive.set(glow ? "#fff1d0" : "#000000");
          surface.emissiveIntensity = glow ? 0.8 : 0;
        }
        if (material.name === BODY_MATERIAL_NAME && "color" in surface) {
          surface.map = null;
          surface.color.set("#1F4E79");
          surface.metalness = 0.62;
          surface.roughness = 0.32;
        }
        surface.transparent = glass;
        surface.opacity = glass ? 0.45 : 1;
        surface.depthWrite = !glass;
        if (glass) {
          surface.metalness = 0.1;
          surface.roughness = 0.05;
        }
      }
    });
  }, [scene]);

  useLayoutEffect(() => {
    const size = bounds.getSize(new THREE.Vector3());
    const center = bounds.getCenter(new THREE.Vector3());
    const longest = Math.max(size.x, size.y, size.z) || 1;
    const aspect = viewport.width / Math.max(viewport.height, 1);
    const scale = Math.min(6.2, Math.max(3.1, 4.4 * aspect)) / longest;
    scene.scale.setScalar(scale);
    scene.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
  }, [bounds, scene, viewport.height, viewport.width]);

  return <primitive object={scene} />;
}

function Turntable({ children }: { children: ReactNode }) {
  const group = useRef<THREE.Group>(null);
  const dragging = useRef(false);
  const reduce = useRef(false);
  const canvas = useThree((state) => state.gl.domElement);

  useEffect(() => {
    reduce.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const start = () => {
      dragging.current = true;
    };
    const stop = () => {
      dragging.current = false;
    };
    canvas.addEventListener("pointerdown", start);
    window.addEventListener("pointerup", stop);
    window.addEventListener("pointercancel", stop);
    return () => {
      canvas.removeEventListener("pointerdown", start);
      window.removeEventListener("pointerup", stop);
      window.removeEventListener("pointercancel", stop);
    };
  }, [canvas]);

  useFrame((_, delta) => {
    if (reduce.current || dragging.current || !group.current) return;
    group.current.rotation.y += delta * 0.16;
  });

  return <group ref={group}>{children}</group>;
}

function GarageWindows() {
  const image = useTexture(WINDOW_IMAGE);
  const texture = useMemo(() => {
    const cropped = image.clone();
    cropped.colorSpace = THREE.SRGBColorSpace;
    // Sample just the window frame, excluding the image's black outer margins.
    cropped.repeat.set(2132 / 2172, 456 / 724);
    cropped.offset.set(20 / 2172, 134 / 724);
    cropped.needsUpdate = true;
    return cropped;
  }, [image]);

  return (
    <mesh position={[-4, 2.9, -4.5]} rotation={[0, Math.atan2(7.2, 8.1), 0]}>
      <planeGeometry args={[9, 9 * 456 / 2132]} />
      <meshBasicMaterial map={texture} toneMapped={false} />
    </mesh>
  );
}

function HomeScene() {
  return (
    <div
      role="application"
      aria-label="Car model turning slowly. Drag to rotate."
      className="h-full w-full cursor-grab bg-white active:cursor-grabbing"
    >
      <Canvas
        camera={{ position: [7.2, 1.7, 8.1], fov: 26 }}
        dpr={[1, 1.5]}
        gl={{ antialias: true }}
        onCreated={({ gl, camera }) => {
          gl.setClearColor(0xffffff, 1);
          camera.lookAt(0, 1.05, 0);
        }}
      >
        <color attach="background" args={["#ffffff"]} />
        <hemisphereLight args={["#e7f2f4", "#2e3440", 0.85]} />
        <ambientLight intensity={0.45} />
        <directionalLight position={[6, 8, 4]} intensity={1.45} />
        <directionalLight position={[-4, 3, -2]} intensity={0.35} />
        <Suspense fallback={null}>
          <PresentationControls global polar={[0, 0]} speed={2}>
            <Turntable>
              <Car />
            </Turntable>
          </PresentationControls>
        </Suspense>
        <Suspense fallback={null}>
          <GarageWindows />
        </Suspense>
        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.02, 0]}>
          <circleGeometry args={[3.15, 64]} />
          <meshStandardMaterial color="#d4d4d4" />
        </mesh>
      </Canvas>
    </div>
  );
}

const HomeCar = dynamic(() => Promise.resolve(HomeScene), { ssr: false });

export default function Home() {
  return (
    <section className="relative h-dvh overflow-hidden bg-white">
      <HomeCar />
      <p className="pointer-events-none absolute inset-x-0 bottom-3 px-4 text-center text-xs text-muted">
        {COPY.stylisedVehicle} {COPY.footer}
      </p>
    </section>
  );
}
